package in.recallradar;
import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.time.*;
@Service @Transactional class AuthService { private final UserRepository users; private final RefreshRepository refreshes; private final ResetRepository resets; private final PasswordEncoder encoder; private final TokenService tokens; private final AppProperties props; private final TenantService tenants;
 AuthService(UserRepository u,RefreshRepository r,ResetRepository p,PasswordEncoder e,TokenService t,AppProperties a,TenantService tenants){users=u;refreshes=r;resets=p;encoder=e;tokens=t;props=a;this.tenants=tenants;}
 TokenResponse register(RegisterRequest r){if(!props.setupCode().equals(r.setupCode()))throw bad("Registration needs a valid organization setup code.");var email=r.email().trim().toLowerCase();if(users.findByEmailIgnoreCase(email).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"An account already exists for this email.");var user=users.save(new AppUser(r.fullName().trim(),email,encoder.encode(r.password())));tenants.createWorkspace(user,r.organizationName());return issue(user);}
 TokenResponse login(LoginRequest r){var u=users.findByEmailIgnoreCase(r.email().trim()).filter(x->x.enabled&&encoder.matches(r.password(),x.passwordHash)).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password."));return issue(u);}
 TokenResponse refresh(RefreshRequest r){var old=refreshes.findByTokenHash(tokens.hash(r.refreshToken())).filter(x->x.revokedAt==null&&x.expiresAt.isAfter(Instant.now())).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Refresh session is invalid or expired.")); old.revokedAt=Instant.now(); return issue(users.findById(old.userId).orElseThrow());}
 void logout(RefreshRequest r){refreshes.findByTokenHash(tokens.hash(r.refreshToken())).ifPresent(x->x.revokedAt=Instant.now());}
 ResetResponse requestReset(ResetRequest r){var user=users.findByEmailIgnoreCase(r.email().trim()); if(user.isEmpty())return new ResetResponse("If the account exists, reset instructions have been created.",null);var raw=tokens.opaque();resets.save(new PasswordResetToken(user.get().id,tokens.hash(raw)));return new ResetResponse("If the account exists, reset instructions have been created.",raw);}
 void reset(ResetConfirmRequest r){var x=resets.findByTokenHash(tokens.hash(r.token())).filter(v->v.usedAt==null&&v.expiresAt.isAfter(Instant.now())).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Reset link is invalid or expired."));var u=users.findById(x.userId).orElseThrow();u.passwordHash=encoder.encode(r.password());x.usedAt=Instant.now();refreshes.findAll().stream().filter(s->s.userId.equals(u.id)&&s.revokedAt==null).forEach(s->s.revokedAt=Instant.now());}
 UserResponse current(String id){var u=users.findById(java.util.UUID.fromString(id)).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));tenants.ensureWorkspace(u);return new UserResponse(u.id.toString(),u.fullName,u.email,u.role);}
 private TokenResponse issue(AppUser u){var raw=tokens.opaque();refreshes.save(new RefreshSession(u.id,tokens.hash(raw),Instant.now().plusSeconds(props.refreshDays()*86400)));return new TokenResponse(tokens.access(u),raw,"Bearer",props.accessMinutes()*60);}
 private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);}
}
